/* Ordi : 3 cartes par ligne (grille de 6 colonnes, chaque carte en couvre
   2), Tous les comptes avant Mon compte, Tutoriel et Événements centrés
   ensemble sur la dernière ligne ; pour les administrateurs, Tutoriel,
   Événements et Administration remplissent la dernière ligne.
   Entre-deux : 2 par ligne, Administration seule centrée sur la dernière. */
@media (min-width: 1001px) {
  .accueil-sections {
    grid-template-columns: repeat(6, minmax(0, 1fr));
  }

  .carte-section {
    grid-column: span 2;
  }

  .carte-derniere {
    grid-column: 2 / span 2;
  }

  .carte-evenements {
    grid-column: 4 / span 2;
  }

  .accueil-sections:has(.carte-admin:not([hidden])) .carte-derniere,
  .accueil-sections:has(.carte-admin:not([hidden])) .carte-evenements {
    grid-column: span 2;
  }

  /* 1re ligne : Tous les comptes au milieu, Mon compte à droite. */
  .carte-tous-comptes {
    grid-row: 1;
    grid-column: 3 / span 2;
  }

  .carte-mon-compte {
    grid-row: 1;
    grid-column: 5 / span 2;
  }
}

@media (min-width: 701px) and (max-width: 1000px) {
  .accueil-sections {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .carte-admin {
    grid-column: 1 / -1;
    justify-self: center;
    width: calc(50% - 0.5625rem);
  }
}

