  /* 1re ligne : Tous les comptes au milieu, Mon compte à droite. */
  .carte-tous-comptes {
    grid-row: 1;
    grid-column: 3 / span 2;
  }

  .carte-mon-compte {
    grid-row: 1;
    grid-column: 5 / span 2;
  }
}

@media (min-width: 701px) and (max-width: 1000px) {
  .accueil-sections {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .carte-admin {
    grid-column: 1 / -1;
    justify-self: center;
    width: calc(50% - 0.5625rem);
  }
}

